  h.assertTrue(track.xp()==2000&&track.completedQuestIds().size()==14,"Starts from genuine8A+6J native mining/growth/geology only");var config=server.getWorldPath(LevelResource.ROOT).resolve("serverconfig/kingdomsmp-commission-quests.json");CommissionQuestRules.get(server);var rules=JsonParser.parseString(java.nio.file.Files.readString(config)).getAsJsonObject();rules.getAsJsonObject("goals").addProperty("kingdom_smp:miner/j07",1);java.nio.file.Files.writeString(config,new Gson().toJson(rules));CommissionQuestRules.clear(server);CreateCraftRuntime.counter(p,mine);var terms=ContractRules.get(server).get("miner/weekly");int before=p.getInventory().countItem(terms.item());for(int n=terms.quantity();n>0;n-=64)h.assertTrue(p.getInventory().add(new ItemStack(terms.item(),Math.min(n,64))),"Private supplied real contract materials fit ordinary inventory");long pool=store.contractPoolSpent("weekly",ContractRules.period("weekly"));var contract=ContractService.review(p,"miner/weekly");ContractService.confirm(p,contract.nonce());boolean replay=false;try{ContractService.confirm(p,contract.nonce());}catch(IllegalStateException expected){replay=true;}h.assertTrue(replay&&p.getInventory().countItem(terms.item())==before&&store.contractPoolSpent("weekly",ContractRules.period("weekly"))==pool+terms.reward()&&store.commissionContractPeriods(p.getUUID(),"kingdom_smp:miner/j07")==1,"Actual native material debit/finite funded weekly mail/single scoped receipt/replay refusal");var quote=ProfessionService.review(p,"quest:kingdom_smp:miner/j07");ProfessionService.confirm(p,quote.nonce());h.assertTrue(store.professions(p.getUUID()).track(Profession.MINER).xp()==2200,"Actual funded weekly completion earns200XP");
