 static void repair(GameTestHelper h,net.minecraft.server.level.ServerPlayer p)throws Exception{var level=p.serverLevel();var route=MineAccessSavedData.get(p.server).evidence().route(p.getUUID()).orElseThrow();for(long cell:route.cells())level.getChunkAt(BlockPos.of(cell));var pos=MineAccessRuntime.at(12);BlacksmithRepairRuntime.near(p,pos);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_PICKAXE));h.assertTrue(p.gameMode.destroyBlock(pos)&&MineAccessSavedData.get(p.server).evidence().mark(new MineAccessEvidence.Cell("minecraft:overworld",pos.asLong())).isEmpty(),"Real native removal invalidates owned support after advancement");for(var entity:level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(pos).inflate(2)))if(entity.getItem().is(Items.COBBLESTONE_STAIRS)){entity.setNoPickUpDelay();entity.playerTouch(p);}int slot=p.getInventory().findSlotMatchingItem(new ItemStack(Items.COBBLESTONE_STAIRS));h.assertTrue(slot>=0,"Original physical support drops are recovered through native pickup");p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,p.getInventory().removeItem(slot,1));p.setYRot(180);p.gameMode.useItemOn(p,level,p.getMainHandItem(),net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(pos.below()).add(0,.5,0),Direction.UP,pos.below(),false));h.assertTrue(p.getMainHandItem().isEmpty(),"Native repair consumes original recovered stair, no extra material minted");var unknown=MineAccessRuntime.ROOT.west(6).above(3);h.assertTrue(level.getBlockState(unknown).isAir()&&level.getBlockState(unknown.below()).isAir(),"Unrelated placement uses empty private test cells only");level.setBlock(unknown.below(),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),18);MineAccessRuntime.place(h,p,unknown,Items.COBBLESTONE_STAIRS,180);h.runAfterDelay(3,()->{try{h.assertTrue(MineAccessSavedData.get(p.server).evidence().mark(new MineAccessEvidence.Cell("minecraft:overworld",pos.asLong())).orElseThrow().player().equals(p.getUUID()),"Later-band owner can reauthenticate actual native replacement on the original route");h.assertTrue(MineAccessSavedData.get(p.server).evidence().mark(new MineAccessEvidence.Cell("minecraft:overworld",unknown.asLong())).isEmpty(),"Unknown later-band placements cannot become new route evidence");MineAccessService.validate(p);h.assertTrue(CommerceService.store(p.server).professions(p.getUUID()).track(Profession.MINER).xp()==2400,"Physical maintenance never reawards descent XP or opens new movement credit");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("MINE_PLAN_RESTART_PASSED: all16earned2400XP/Master trials/native receipt/route/weekly service/plan audit/Mine-Doran restore; actual original-stair drop pickup+consumed repair remains possible after advancement, unrelated placed supports grant no new route/XP");h.succeed();}catch(Exception error){h.fail(error.toString());}});}
